describe("doctests of sympy.polys.numberfields.minpoly", () => {
  it("minimal_polynomial(sqrt(2) + 3*Rational(1, 3), x, compose=True)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(1, pow(2, rational(1, 2))), x, { compose: true, polys: false }))).toBe('x**2 - 2*x - 1');
  });
  it("minimal_polynomial(sqrt(y) + 1/y, x, compose=True)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(minimalPolynomial(add(pow(y, rational(1, 2)), pow(y, -1)), x, { compose: true, polys: false }))).toBe('x**2*y**2 - 2*x*y - y**3 + 1');
  });
  it("minimal_polynomial(sqrt(2) + 3*Rational(1, 3), x, compose=False)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(1, pow(2, rational(1, 2))), x, { compose: false, polys: false }))).toBe('x**2 - 2*x - 1');
  });
  it("minpoly(p**2, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(1, pow(2, rational(1, 2))), x, { compose: true, polys: false }))).toBe('x**2 - 2*x - 1');
  });
  it("minpoly(y**Rational(1, 3), x)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(minimalPolynomial(pow(y, rational(1, 3)), x, { compose: true, polys: false }))).toBe('x**3 - y');
  });
  it("minimal_polynomial(sqrt(2), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(pow(2, rational(1, 2)), x, { compose: true, polys: false }))).toBe('x**2 - 2');
  });
  // no value
  //   minimal_polynomial(sqrt(2), x, domain=QQ.algebraic_field(sqrt(2)))
  //   => x - sqrt(2)
  it.todo("minimal_polynomial(sqrt(2), x, domain=QQ.algebraic_field(sqrt(2)))");
  it("minimal_polynomial(sqrt(2) + sqrt(3), x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(pow(2, rational(1, 2)), pow(3, rational(1, 2))), x, { compose: true, polys: false }))).toBe('x**4 - 10*x**2 + 1');
  });
  it("minimal_polynomial(solve(x**3 + x + 3)[0], x)", () => {
    const x = new Sym('x');
    expect(sympyStr(minimalPolynomial(add(mul(pow(add(rational(-1, 2), mul(rational(-1, 2), I, pow(3, rational(1, 2)))), -1), pow(add(rational(81, 2), mul(rational(3, 2), pow(741, rational(1, 2)))), rational(-1, 3))), mul(rational(-1, 3), pow(add(rational(81, 2), mul(rational(3, 2), pow(741, rational(1, 2)))), rational(1, 3)), add(rational(-1, 2), mul(rational(-1, 2), I, pow(3, rational(1, 2)))))), x, { compose: true, polys: false }))).toBe('x**3 + x + 3');
  });
  it("minimal_polynomial(sqrt(y), x)", () => {
    const [y, x] = symbols('y x');
    expect(sympyStr(minimalPolynomial(pow(y, rational(1, 2)), x, { compose: true, polys: false }))).toBe('x**2 - y');
  });
});

